#!/usr/bin/env python3
"""
Round 147i (culprits), 3 October 2026. Needs round 146h.

Indigenous, a fifth basemap.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 147i (3 October)\n\nNeeds round 146h. No tiles patch. No app.js?v= bump. Indigenous basemap only.\n\n- A fifth basemap, Indigenous (asked 3 October, after the owner\'s pictures: a\n  hand-painted relief map of Canada\'s First Peoples and painted hunting\n  scenes; "blend them all" into one). Built from what peoples on every\n  continent share rather than any one nation\'s designs: the earth pigments\n  (red ochre, white clay, charcoal, indigo) and the painted-relief look. No\n  motifs that belong to particular peoples, no portraits. Indigo sea, darker\n  in the deeps and paler on the shelves (AWS terrain heights, sea-dem); land\n  from pale clay through red ochre and charcoal to white clay on the highest\n  peaks; warm daylight relief over umber shadow (Mapterhorn); forests as a\n  slate-teal wash, ice in white clay, wetlands in indigo, lakes and rivers\n  indigo, towns clay grey, roads charcoal brown, borders a faint charcoal\n  dash (OpenFreeMap, boundaries); place names in grey ink. No orange,\n  yellow or green; a test checks the colours.\n- Layers outline-indig-* (INDIG_IDS), one block of app.js ("Indigenous, a\n  fifth basemap" to "end of Indigenous"), reached by wrapping\n  basemapPanelHtml and setBasemap after Hell\'s wrappers. Not seen against\n  real tiles (the sandbox cannot reach them): check the look live.\n']


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round147i: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 146h" not in h.read_text(encoding="utf-8"):
        sys.exit("round147i: round 146h must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round147i: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round147i: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round147i: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


DIFF = ''

if __name__ == "__main__":
    main()
